import java.util.*;

public String toJsonLike(Map<String, String> map) {
    StringBuilder sb = new StringBuilder();
    sb.append('{');
    boolean first = true;
    for (Map.Entry<String, String> e : map.entrySet()) {
        if (!first) sb.append(',');
        first = false;
        sb.append("\"").append(e.getKey()).append("\"").append(':')
          .append("\"").append(e.getValue()).append("\"");
    }
    sb.append('}');
    return sb.toString();
}

